import re
from typing import Any, Optional, List, Tuple, Union

class LexerError(Exception):
    pass

class ParseError(Exception):
    pass

class TypeError:
    pass

class Interpreter:
    def __init__(self):
        self.variables: dict = {}
        self.position: int = 0
        self.tokens: List[Token] = []

    def reset(self):
        self.variables = {}
        self.position = 0
        self.tokens = []

    def tokenize(self, source: str) -> List[Token]:
        # Tokenizasyon
        tokens = []
        line_comment_pattern = re.compile(r'#[^\n]*')
        source = line_comment_pattern.sub('', source)
        source = re.sub(r'#[^\n]*', '', source)

        # Satır sonları ve ; ile ayır
        statements = re.split(r'(?<=[;])|\n', source)
        i = 0
        while i < len(statements):
            s = statements[i].strip()
            i += 1
            if not s:
                continue
            tokens.extend(self._tokenize_statement(s))
        return tokens

    def _tokenize_statement(self, s: str) -> List[Token]:
        # Basit tokenizasyon
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
                continue
            # Parantez
            if s[i] in '()':
                tokens.append(Token(s[i], i))
                i += 1
                continue
            # Parantez açma
            if s[i] == '(':
                # Parantez içi: parantez açma, sayı, değişken
                # Token: '(', '('
                pass
            # İki haneli sayı
            if s[i:i+2].isdigit():
                tokens.append(Token(s[i:i+2], i))
                i += 2
                continue
            if s[i].isdigit():
                # Tam sayı veya ondalıklı
                j = i
                while j < len(s) and (s[j].isdigit() or s[j] in '.'):
                    j += 1
                tokens.append(Token(s[i:j], i))
                i = j
                continue
            # Değişken
            if s[i].isalpha() or s[i] == '_':
                j = i
                while j < len(s) and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                tokens.append(Token(s[i:j], i))
                i = j
                continue
            # İşleçler
            if s[i] in '+-*/%':
                tokens.append(Token(s[i], i))
                i += 1
                continue
            if s[i] == '=':
                tokens.append(Token(s[i], i))
                i += 1
                continue
            if s[i] == '^':
                tokens.append(Token(s[i], i))
                i += 1
                continue
            # Bilinmeyen
            raise ParseError(f"Satır '{s}': bilinmeyen karakter '{s[i]}'")
        return tokens

    def parse(self, tokens: List[Token]) -> Any:
        self.tokens = tokens
        self.position = 0
        return self.parse_expression(0)

    def parse_expression(self, precedence: int) -> Any:
        # 0: + -
        # 1: * / %
        # 2: tekli - +
        # 3: **

        # Önce tekli + ve -'leri işle
        left = self.parse_primary()

        while self.position < len(self.tokens):
            token = self.tokens[self.position]

            if token.type == '+':
                self.position += 1
                right = self.parse_expression(0)
                left = left + right
            elif token.type == '-':
                self.position += 1
                right = self.parse_expression(0)
                left = left - right
            elif token.type == '*':
                self.position += 1
                right = self.parse_expression(1)
                left = left * right
            elif token.type == '/':
                self.position += 1
                right = self.parse_expression(1)
                if right == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                left = left / right
            elif token.type == '%':
                self.position += 1
                right = self.parse_expression(1)
                if right == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                left = left % right
            elif token.type == '^':
                self.position += 1
                right = self.parse_expression(3)
                left = left ** right
            else:
                break

        return left

    def parse_primary(self) -> Any:
        if self.position >= len(self.tokens):
            return None

        token = self.tokens[self.position]

        if token.type == '(':
            self.position += 1
            expr = self.parse_expression(0)
            if self.position >= len(self.tokens) or self.tokens[self.position].type != ')':
                raise ParseError("Parantez kapama hatası")
            self.position += 1
            return expr

        if token.type in '+-*/%^()':
            raise ParseError(f"Beklenmeyen token: {token.type}")

