from typing import Any, Optional, List, Tuple, Union

class Token:
    def __init__(self, type_: str, value: str):
        self.type = type_
        self.value = value

class LexerError(Exception):
    pass

class ParseError(Exception):
    pass

class TokenType:
    NUMBER = 'NUMBER'
    IDENTIFIER = 'IDENTIFIER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    STAR = 'STAR'
    SLASH = 'SLASH'
    PERCENT = 'PERCENT'
    CARET = 'CARET'      # ** için
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    ASSIGN = 'ASSIGN'
    COMMA = 'COMMA'
    EOF = 'EOF'

class Interpreter:
    def __init__(self, variables: dict = None):
        self.variables = variables if variables else {}
        self.position = 0
        self.tokens: List[Token] = []
        self.error_message: Optional[str] = None

    def reset(self):
        self.variables = self.variables.copy()
        self.position = 0
        self.tokens = []
        self.error_message = None

    def tokenize(self, source: str) -> List[Token]:
        # Önce yorum satırlarını kaldır (# satırın kalanını yorum)
        lines = source.split('\n')
        cleaned_lines = []
        for line in lines:
            # # karakterinden sonrası yorum
            idx = line.find('#')
            if idx >= 0:
                line = line[:idx]
            cleaned_lines.append(line)
        source = '\n'.join(cleaned_lines)

        # Satır sonları ve ; ile ayır
        raw_statements = re.split(r'(?<=[;])\n?', source)
        statements = []
        for s in raw_statements:
            s = s.strip()
            if s:
                statements.append(s)

        tokens = []
        for stmt in statements:
            tokens.extend(self._tokenize(stmt))

        if tokens:
            tokens.append(Token(TokenType.EOF, ''))
        return tokens

    def _tokenize(self, s: str) -> List[Token]:
        tokens = []
        i = 0
        n = len(s)

        while i < n:
            # Boşluklar
            if s[i].isspace():
                i += 1
                continue

            # Parantezler
            if s[i] == '(':
                tokens.append(Token(TokenType.LPAREN, '('))
                i += 1
                continue
            if s[i] == ')':
                tokens.append(Token(TokenType.RPAREN, ')'))
                i += 1
                continue

            # Sayılar
            if s[i].isdigit():
                j = i
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                tokens.append(Token(TokenType.NUMBER, s[i:j]))
                i = j
                continue

            # Değişkenler
            if s[i].isalpha() or s[i] == '_':
                j = i
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                tokens.append(Token(TokenType.IDENTIFIER, s[i:j]))
                i = j
                continue

            # İşleçler
            if s[i] == '+':
                tokens.append(Token(TokenType.PLUS, '+'))
                i += 1
                continue
            if s[i] == '-':
                tokens.append(Token(TokenType.MINUS, '-'))
                i += 1
                continue
            if s[i] == '*':
                tokens.append(Token(TokenType.STAR, '*'))
                i += 1
                continue
            if s[i] == '/':
                tokens.append(Token(TokenType.SLASH, '/'))
                i += 1
                continue
            if s[i] == '%':
                tokens.append(Token(TokenType.PERCENT, '%'))
                i += 1
                continue
            if s[i] == '^':
                tokens.append(Token(TokenType.CARET, '^'))
                i += 1
                continue
            if s[i] == '=':
                tokens.append(Token(TokenType.ASSIGN, '='))
                i += 1
                continue
            if s[i] == ',':
                tokens.append(Token(TokenType.COMMA, ','))
                i += 1
                continue

            raise ParseError(f"Bilinmeyen karakter: '{s[i]}'")

        return tokens

    def parse(self) -> Any:
        """Toplam ifadeyi parse et."""
        self.tokens = self.tokenize(self.source)
        self.position = 0

        # Önce tekli işareti kontrol et (+ veya -)
        if self.tokens and self.tokens[0].type in (TokenType.PLUS, TokenType.MINUS):
            op_token = self.tokens.pop(0)
            expr = self.parse_unary()
            return ('unary', op_token.type, expr)

        # Atama var mı?
        left = self.parse_assignment_expr()

        # Atama varsa sağ tarafı parse et
        if self.position < len(self.tokens) and self.tokens[self.position].type == TokenType.ASSIGN:
            self.position += 1  # Skip '='
            right = self.parse_assignment_expr()

            # Sağ tarafı değerlendir
            right_value = self.eval_expression(right)

            # Sol taraf değişken adı olmalı
            if isinstance(left, str):
                # Değişken ataması
                self.variables[left] = right_value
                return right_value
            else:
                raise ParseError(f"Atama bekleniyordu: {left} = ...")

        return self.eval_expression(left)

    def parse_assignment_expr(self) -> Any:
        """Atama ifadesini parse et (sol taraf)."""
        return self.parse_primary_or_call()

    def parse_primary_or_call(self) -> Any:
        """
        Bir ifadeyi parse et.
        Dönenler:
        - str: değişken adı
        - int/float: sayı
        - ('call', func_name, arg_expressions): fonksiyon çağrısı
        - ('unary', op, expr): tekli işlemci (internal use)
        """
        if self.position >= len(self.tokens):
            raise ParseError("Beklenen ifade yok")

        token = self.tokens[self.position]

        # Parantez içinde ifade
        if token.type == TokenType.LPAREN:
            self.position += 1
            args = self.parse_args()
            self.position += 1  # Skip ')'

            # args[0] bir fonksiyon adı mı?
            if args:
                first = args[0]
                if isinstance(first, str):
                    # Fonksiyon çağrısı: fonksiyon_ad(arg1, arg2, ...)
                    return ('call', first, args[1:])
                elif isinstance(first, list) and len(first) == 2 and first[0] == 'call':
                    # İç içe fonksiyon çağrısı
                    return first[1]
                else:
                    # Parantez içinde sadece bir ifade: (ifade)
                    return args[0]
            else:
                raise ParseError("Boş parantez: ()")

        # Değişken
        if token.type == TokenType.IDENTIFIER:
            return token.value

        # Sayı
        if token.type == TokenType.NUMBER:
            return float(token.value) if '.' in token.value else int(token.value)

        raise ParseError(f"Bilinmeyen token: {token.type}")

    def parse_args(self) -> List[Any]:
        """Parantez içindeki argümanları parse et (virgülle ayrılmış)."""
        args = []

        while self.position < len(self.tokens):
            token = self.tokens[self.position]

            if token.type == TokenType.COMMA:
                self.position += 1
                continue

            if token.type == TokenType.RPAREN:
                break

            # Argümanı parse et
            arg = self.parse_primary_or_call()
            args.append(arg)

        return args

    def eval_expression(self, expr: Any) -> Any:
        """Bir ifade tree'sini değerlendir."""
        if isinstance(expr, tuple):
            if expr[0] == 'call':
                # Fonksiyon çağrısı
                func_name, func_args = expr[1], expr[2]
                func_args = [self.eval_expression(a) for a in func_args]

                if func_name == 'min':
                    return min(func_args)
                elif func_name == 'max':
                    return max(func_args)
                elif func_name == 'abs':
                    return abs(func_args[0])
                else:
                    raise NameError(f"Tanımsız fonksiyon: {func_name}")
            elif expr[0] == 'unary':
                # Tekli işlemci
                op, inner = expr[1], expr[2]
                inner_value = self.eval_expression(inner)
                if op == '+':
                    return +inner_value
                elif op == '-':
                    return -inner_value
        return expr

    def eval_binary(self, left: Any, op: str, right: Any) -> Any:
        """İki işlemciyi değerlendir."""
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("Sıfıra bölme")
            return left / right
        elif op == '%':
            if right == 0:
                raise ZeroDivisionError("Sıfıra bölme")
            return left % right
        elif op == '^':
            return left ** right
        raise ParseError(f"Bilinmeyen işlemci: {op}")

    def evaluate(self, source: str) -> Any:
        """Kaynak kodu çalıştır."""
        self.source = source
        self.reset()

        # Tokenize
        if not self.tokens or self.tokens[-1].type != TokenType.EOF:
            raise ParseError("Söz dizimi hatası: tokenizasyon eksik")

        # Parse
        result = self.parse()

        # EOF'a gelmeliyiz
        if self.position < len(self.tokens) - 1:
            # Eğer son token değilse, kalan token var demektir
            remaining = self.tokens[self.position:]
            if any(t.type != TokenType.EOF and t.type not in (TokenType.COMMA, TokenType.RPAREN) 
                   for t in remaining):
                raise ParseError(f"Son ifade bekleniyordu: {remaining}")

        return result


def calistir(program: str) -> Any:
    calc = Interpreter({})
    result = None

    for line in program.split('\n'):
        # ; ile ayrılmış parçaları al
        parts = re.split(r'(?<=[;])\n?', line)

        for part in parts:
            part = part.strip()
            if not part:
                continue

            try:
                result = calc.evaluate(part)
            except LexerError as e:
                raise SyntaxError(str(e))
            except ParseError as e:
                raise SyntaxError(str(e))
            except NameError as e:
                raise e
            except ZeroDivisionError as e:
                raise e

    return result
